moveTabBefore(element, targetElement, { metricsContext } = {}) {
  this.#moveTabNextTo(element, targetElement, true, { metricsContext });
}

/**
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup[]} elements
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} targetElement
 * @param {object} [options]
 * @param {TabMetricsContext} [options.metricsContext]
 *   The context for the operation for telemetry purposes.
 */
moveTabsBefore(elements, targetElement, { metricsContext } = {}) {
  this.#moveTabsNextTo(elements, targetElement, true, { metricsContext });
}

/**
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} element
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} targetElement
 * @param {object} [options]
 * @param {TabMetricsContext} [options.metricsContext]
 *   The context for the operation for telemetry purposes.
 */
moveTabAfter(element, targetElement, { metricsContext } = {}) {
  this.#moveTabNextTo(element, targetElement, false, { metricsContext });
}

/**
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup[]} elements
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} targetElement
 * @param {object} [options]
 * @param {TabMetricsContext} [options.metricsContext]
 *   The context for the operation for telemetry purposes.
 */
moveTabsAfter(elements, targetElement, { metricsContext } = {}) {
  this.#moveTabsNextTo(elements, targetElement, false, { metricsContext });
}

/**
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} element
 *   The tab or tab group to move. Also accepts a tab group label as a
 *   stand-in for its group.
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} targetElement
 * @param {boolean} [moveBefore=false]
 * @param {object} [options]
 * @param {TabMetricsContext} [options.metricsContext]
 *   The context for the operation for telemetry purposes.
 */
#moveTabNextTo(
  element,
  targetElement,
  moveBefore = false,
  { metricsContext } = {}
) {
  if (this.isTabGroupLabel(targetElement)) {
    targetElement = targetElement.group;
    if (!moveBefore && !targetElement.collapsed && !targetElement.hasAttribute("split-view-group")) {
      // Right after the tab group label = before the first tab in the tab group
      targetElement = targetElement.tabs[0];
      moveBefore = true;
    }
  }
  if (this.isTabGroupLabel(element) || element.group?.hasAttribute("split-view-group")) {
    element = element.group;
  }

  // Don't allow mixing pinned and unpinned tabs.
  targetElement = this.documentGlobal.gZenGlanceManager.getTabOrGlanceParent(targetElement);
  if (targetElement?.classList.contains('tab-group-label-container')) {
    targetElement = targetElement.parentElement;
  }
  if (element.hasAttribute('zen-essential') && !targetElement?.hasAttribute('zen-essential')) {
    targetElement = this.tabsWithoutGlance[this._numZenEssentials - 1];
  } else
  if (element.pinned && !targetElement?.pinned) {
    targetElement = this.tabsWithoutGlance[this.pinnedTabCount - 1];
    moveBefore = false;
    if (!this.visibleTabs.includes(targetElement)) {
      targetElement = this.documentGlobal.gZenWorkspaces.pinnedTabsContainer.querySelector('.pinned-tabs-container-separator')
      moveBefore = true;
    }
  } else if (!element.pinned && targetElement && targetElement.pinned) {
    // If the caller asks to move an unpinned element next to a pinned
    // tab, move the unpinned element to be the first unpinned element
    // in the tab strip. Potential scenarios:
    // 1. Moving an unpinned tab and the first unpinned tab is ungrouped:
    //    move the unpinned tab right before the first unpinned tab.
    // 2. Moving an unpinned tab and the first unpinned tab is grouped:
    //    move the unpinned tab right before the tab group.
    // 3. Moving a tab group and the first unpinned tab is ungrouped:
    //    move the tab group right before the first unpinned tab.
    // 4. Moving a tab group and the first unpinned tab is grouped:
    //    move the tab group right before the first unpinned tab's tab group.
    targetElement = this.tabsWithoutGlance[this.pinnedTabCount];
    if (targetElement.group) {
      targetElement = targetElement.group;
    }
    moveBefore = true;
  }
  if (!this.documentGlobal.gZenFolders.canDropElement(element, targetElement)) {
    element = element.group;
  }
  if (!element.hasAttribute('zen-essential') && targetElement?.hasAttribute('zen-essential')) {
    targetElement = null;
    moveBefore = false;
  }
  // It is necessary to place the check below to avoid inserting an element
  // inside when the split group is the last element.
  if (targetElement?.group?.hasAttribute("split-view-group")) {
    targetElement = targetElement.group;
  }
  if (targetElement?.hasAttribute("zen-empty-tab")) {
    // When the folder is the last element in the pinned section,
    // targetElement is a tab with the zen-empty-tab attribute.
    // If the movement is from top to bottom, it must be redefined as a folder.
    if (!moveBefore) {
      targetElement = targetElement.group;
    } else {
      // Always insert an element after zen-empty-tab to avoid it moving from the first position
      moveBefore = false;
    }
  }

  // We want to include the splitview wrapper if it's the targetElement, but
  // not in the case where we want to reverse tabs within the same splitview.
  if (targetElement?.splitview && !element.splitview) {
    targetElement = targetElement.splitview;
  }

  let getContainer = () =>
    element.hasAttribute("zen-essential") ? this.documentGlobal.gZenWorkspaces.getEssentialsSection(element) :
    element.pinned
      ? this.tabContainer.pinnedTabsContainer
      : this.tabContainer;

  this.#handleTabMove(
    element,
    () => {
      if (moveBefore) {
        targetElement.parentElement.insertBefore(element, targetElement);
      } else if (targetElement) {
        targetElement.after(element);
      } else {
        if (element.pinned) {
          getContainer().prepend(element);
        } else {
        getContainer().appendChild(element);
        }
      }
    },
    { metricsContext }
  );
}

/**
 * @param {MozTabbrowserTab[]} elements
 * @param {MozTabbrowserTab|MozTabbrowserTabGroup} targetElement
 * @param {boolean} [moveBefore=false]
 * @param {object} [options]
 * @param {TabMetricsContext} [options.metricsContext]
 *   The context for the operation for telemetry purposes.
 */
#moveTabsNextTo(
  elements,
  targetElement,
  moveBefore = false,
  { metricsContext } = {}
) {
  this.recordTabMetrics(this.TabMetrics.METRIC_ACTION.MOVE, metricsContext, {
    tabCount: elements.length,
  });

  this.#moveTabNextTo(elements[0], targetElement, moveBefore, {
    metricsContext: this.TabMetrics.decomposedContext(metricsContext),
  });
  for (let i = 1; i < elements.length; i++) {
    this.#moveTabNextTo(elements[i], elements[i - 1], false, {
      metricsContext: this.TabMetrics.decomposedContext(metricsContext),
    });
  }
}

accepts:
getDropEffectForTabDrag(event) {
  var dt = event.dataTransfer;

  let isMovingTab = dt.mozItemCount > 0;
  for (let i = 0; i < dt.mozItemCount; i++) {
    // tabs are always added as the first type
    let types = dt.mozTypesAt(0);
    if (types[0] != TAB_DROP_TYPE) {
      isMovingTab = false;
      break;
    }
  }

  if (isMovingTab) {
    let sourceNode = dt.mozGetDataAt(TAB_DROP_TYPE, 0);
    if (
      (isTab(sourceNode) ||
        isTabGroupLabel(sourceNode) ||
        isSplitViewWrapper(sourceNode)) &&
      sourceNode.documentGlobal.isChromeWindow &&
      sourceNode.ownerDocument.documentElement.getAttribute("windowtype") ==
        "navigator:browser"
    ) {
      // Do not allow transfering a private tab to a non-private window
      // and vice versa.
      if (
        PrivateBrowsingUtils.isWindowPrivate(window) !=
        PrivateBrowsingUtils.isWindowPrivate(sourceNode.documentGlobal)
      ) {
        return "none";
      }

      if (
        window.gMultiProcessBrowser !=
        sourceNode.documentGlobal.gMultiProcessBrowser
      ) {
        return "none";
      }

      if (
        window.gFissionBrowser != sourceNode.documentGlobal.gFissionBrowser
      ) {
        return "none";
      }

      return dt.dropEffect == "copy" ? "copy" : "move";
    }
  }

  if (Services.droppedLinkHandler.canDropLink(event, true)) {
    return "link";
  }
  return "none";
}
